# Shared definition of the managed target set for script/link and
# script/check. Sourced, never executed directly: both commands must agree
# on exactly which $HOME entries dotfiles manages, so the enumeration
# (whole-directory units, composer-owned exclusions, per-file sources)
# lives here once instead of being duplicated in each script.

# Claude settings are generated by script/claude-settings.ts, not symlinked.
# Skip the canonical file the composer owns and any backup the composer may
# have left in the working tree (home/.claude/*.bak from migrations, or the
# older pre-dotfiles-* pattern). Leaving these under HOME is harmless: the
# composer writes its backups under the state directory, never next to the
# live file, and these leftovers must never be promoted to a managed target.
managed_is_composer_owned() {
  local relative="$1"
  case "$relative" in
    .claude/settings.json) return 0 ;;
    .claude/*.bak) return 0 ;;
    .claude/*.pre-dotfiles-*) return 0 ;;
    snippets/*) return 0 ;;
  esac
  return 1
}

# Top-level unit names discovered by managed_sources; matched exactly, never
# word-split or substring-matched (names may contain spaces).
MANAGED_UNIT_NAMES=()

managed_is_unit_name() {
  local candidate="$1" name
  [[ ${#MANAGED_UNIT_NAMES[@]} -gt 0 ]] || return 1
  for name in "${MANAGED_UNIT_NAMES[@]}"; do
    [[ "$name" == "$candidate" ]] && return 0
  done
  return 1
}

# A top-level entry of home/ is linked as ONE symlink when it is a committed
# symlink (home/.dsh -> ../agents/dsh) or a git submodule checkout. That keeps
# a submodule pinned under agents/ reachable from $HOME while $HOME/<name> is
# still a symlink to the pinned checkout. Every other file keeps the original
# per-file symlink behaviour.
managed_discover_units() {
  local source_root="$1"
  local entry

  MANAGED_UNIT_NAMES=()

  shopt -s nullglob dotglob
  for entry in "$source_root"/*; do
    [[ -e "$entry" || -L "$entry" ]] || continue
    if [[ -L "$entry" || -e "$entry/.git" ]]; then
      MANAGED_UNIT_NAMES+=("$(basename "$entry")")
    fi
  done
  shopt -u nullglob dotglob
}

# Emit every managed source under $1 (the home/ mirror root) as NUL-separated
# paths: whole-directory units first so a parent exists before any per-file
# source lands inside it, then the remaining files.
managed_sources() {
  local source_root="$1"
  local name source relative first

  managed_discover_units "$source_root"

  if [[ ${#MANAGED_UNIT_NAMES[@]} -gt 0 ]]; then
    for name in "${MANAGED_UNIT_NAMES[@]}"; do
      printf '%s\0' "$source_root/$name"
    done
  fi

  while IFS= read -r -d '' source; do
    relative="${source#"$source_root"/}"
    first="${relative%%/*}"
    managed_is_unit_name "$first" && continue
    managed_is_composer_owned "$relative" && continue
    printf '%s\0' "$source"
  done < <(find "$source_root" \( -type f -o -type l \) -print0)
}
